const {realVar, vectorVar, vec} = Symbolic;
const {fitDataAsync} = DataScience;
let trainXs = NArray.range(0,1000).map(x => 2 * Math.random() - 1);
let testXs = NArray.range(0,1000).map(x => 2 * Math.random() - 1);
let yf = x => 4 * x * x * x - 2 * x * x + 3 * x - 3 + (2 * Math.random() - 1);

let plot = IO.plotPointCloud(trainXs.map(x => [x, yf(x)]));
let curve = plot.add([], {color: [0, 0, 1]});

let x = realVar("x", true);
let a = vectorVar("a", 4);
let f = vec(1, x, x.mul(x), x.mul(x).mul(x)).dot(a);

const updateCurve = (compiledModel, theta) => {
    curve.update(testXs.map(x => [x, compiledModel({x, ...theta})]));
    plot.render();
};
setTimeout(async () => {
    const {compiledModel, theta} = await fitDataAsync(trainXs, trainXs.map(yf), f, {
        epochs: 10000,
        continuationEvery: 100,
        continuationFn: ({compiledModel, theta}) => updateCurve(compiledModel, theta),
    });
    updateCurve(compiledModel, theta);
});
plot;
